"""Validate only PDFs generated by the isolated presentation browser suite."""
import json
import re
import sys
import unicodedata
from pathlib import Path

import pypdfium2 as pdfium
from pypdf import PdfReader

folder = Path(sys.argv[1]).resolve()
results = json.loads((folder / "presentation-pdf-results.json").read_text(encoding="utf-8"))["results"]
combinations = {(case["count"], case["language"], case["price"], case["plants"]) for case in results}
assert len(results) == len(combinations) == 16, "Expected the 16 distinct generated PDFs"
assert len(list(folder.glob("Apresenta*_TheView-pt-*.pdf"))) == len(results)


def normalize(text):
    text = " ".join(unicodedata.normalize("NFKC", text).split())
    return re.sub(r"(?<=\w)-\s+(?=\w)", "-", text)


pages_checked = 0
for case in results:
    file = folder / case["file"]
    reader = PdfReader(file)
    assert len(reader.pages) == case["count"], (file.name, len(reader.pages))
    assert reader.metadata.title == case["title"]
    rendered = pdfium.PdfDocument(str(file))
    for index, page in enumerate(reader.pages):
        text = page.extract_text()
        assert text.count("Documento meramente informativo") == 1
        assert ("€" in text) == case["price"]
        assert "NaN" not in text and "undefined" not in text
        assert bool(page.images) == case["plants"], "Floor plan must match the print option"
        assert abs(float(page.mediabox.width) - 595.28) < 2
        assert abs(float(page.mediabox.height) - 841.89) < 2
        pdf_page = rendered[index]
        width, height = pdf_page.get_size()
        images = [obj.get_bounds() for obj in pdf_page.get_objects() if isinstance(obj, pdfium.PdfImage)]
        assert bool(images) == case["plants"]
        assert all(20 <= left < right <= width - 20 and 20 <= bottom < top <= height - 20
                   for left, bottom, right, top in images)
        # PDF coordinates start at the bottom. The entire notice must be below the plan.
        footer_top = min([150] + [bounds[1] - 1 for bounds in images])
        footer = pdf_page.get_textpage().get_text_bounded(left=20, bottom=20, right=width - 20, top=footer_top)
        expected_footer = " ".join(p["text"] for p in case["footers"][index]["paragraphs"]) + " " + case["footers"][index]["generated"]
        assert normalize(footer) == normalize(expected_footer), (file.name, index + 1)
        image = pdf_page.render(scale=1.5).to_pil()
        assert image.convert("L").getextrema()[0] < 128, "Blank rendered page"
        image.save(folder / f"{file.stem}-page-{index + 1}.png")
        pages_checked += 1
    rendered.close()
print(json.dumps({"pdfs": len(results), "pages": pages_checked,
                  "a4_portrait": True, "titles": True, "prices": True,
                  "plans_by_option": True, "complete_footer_below_content": True, "rendered": True}))
